import { THEME_MODES } from "@rapid7/rds-theme-metadata-provider";
import { darkPalette } from "./darkPalette";
import { lightPalette } from "./lightPalette";
import { getPaletteOptionsForPaletteMap } from "../../coreTheme/palette/getPaletteOptionsForPaletteMap";
const paletteMap = {
    [THEME_MODES.DARK]: darkPalette,
    [THEME_MODES.LIGHT]: lightPalette,
};
/**
 * Get the palette for the given theme mode
 * @param {ThemeMode} themeMode - The theme mode
 * @returns {PaletteOptions} The palette for the given theme mode
 */
export const getPalette = (themeMode) => {
    return getPaletteOptionsForPaletteMap(themeMode, paletteMap);
};
